#!/usr/bin/env bash
set -Eeuo pipefail

STAGE_VERSION="rnatr_general_repeat_caller_disease_sim_and_expansion_patch_wrapper_v0.4.1"
PROJECT_ROOT="/mnt/intelssd/rnatr_project"
SRC_DIR="$PROJECT_ROOT/src/rnatr_scout/general_caller"
SCRIPT_DIR="$PROJECT_ROOT/scripts"
CALLER_V02="$SRC_DIR/rnatr_general_repeat_caller_ref_v0.2.0.py"
CALLER_V03="$SRC_DIR/rnatr_general_repeat_caller_ref_v0.3.0.py"
CALLER_V04="$SRC_DIR/rnatr_general_repeat_caller_ref_v0.4.0.py"
BENCH_SCRIPT="$SCRIPT_DIR/rnatr_general_repeat_caller_disease_sim_benchmark_v0.4.0.py"
SELFTEST_V01="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.1.0/rnatr_general_repeat_caller_fixture_selftest_v0.1.0.py"
SELFTEST_V02="$SCRIPT_DIR/rnatr_general_repeat_caller_fixture_selftest_v0.2.0.py"
SELFTEST_V03="$SCRIPT_DIR/rnatr_general_repeat_caller_boundary_censor_denovo_selftest_v0.3.0.py"
FIXTURES_REAL="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.2.0/real_p01_regression_materialized.tsv"
QC12D="$PROJECT_ROOT/qc/12_general_repeat_caller_boundary_censor_denovo/v0.3.0/general_repeat_caller_stage12d.qc.tsv"
V03_REAL_QC="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.3.0/real_p01_regression.qc.tsv"
BENCH="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.4.0_stage12e_wrapper_v0.4.1"
QC_DIR="$PROJECT_ROOT/qc/12_general_repeat_caller_disease_sim/v0.4.0_stage12e_wrapper_v0.4.1"
STAGE_QC="$QC_DIR/general_repeat_caller_stage12e.qc.tsv"
NOTE="$PROJECT_ROOT/docs/design/RNA_TR_Scout_general_repeat_caller_reference_v0.4.0.md"
TMP="$PROJECT_ROOT/tmp/12_general_repeat_caller_disease_sim/v0.4.0_stage12e_wrapper_v0.4.1"
CANDIDATE="$TMP/rnatr_general_repeat_caller_ref_v0.4.0.candidate.py"
SCRIPT_INSTALL="$SCRIPT_DIR/12e_run_disease_sim_and_promote_v0.4.1.sh"

for p in "$CALLER_V02" "$CALLER_V03" "$SELFTEST_V01" "$SELFTEST_V02" "$SELFTEST_V03" "$FIXTURES_REAL" "$QC12D" "$V03_REAL_QC"; do
  [[ -s "$p" ]] || { echo "ERROR: required Stage 12E input missing: $p" >&2; exit 2; }
done

status12d="$(awk -F '\t' '$1=="audit_status"{print $2}' "$QC12D" | tr -d '\015' | tail -n1)"
[[ "$status12d" == "PASS" ]] || { echo "ERROR: Stage 12D not PASS: $status12d" >&2; exit 2; }

expected_v02_sha="e66c21e3d6f35744f40014726402b2d30234eb76824b06c12d04b8f1e05caf57"
actual_v02_sha="$(sha256sum "$CALLER_V02" | awk '{print $1}')"
[[ "$actual_v02_sha" == "$expected_v02_sha" ]] || {
  echo "ERROR: unexpected v0.2.0 caller SHA; refusing benchmark dependency copy" >&2
  echo "expected=$expected_v02_sha" >&2
  echo "actual=$actual_v02_sha" >&2
  exit 2
}

expected_v03_sha="6f201a30562227384fb18067c56ecfc1b4859fc2ed65d119f07ae90184aec5b3"
actual_v03_sha="$(sha256sum "$CALLER_V03" | awk '{print $1}')"
[[ "$actual_v03_sha" == "$expected_v03_sha" ]] || {
  echo "ERROR: unexpected v0.3.0 caller SHA; refusing blind patch" >&2
  echo "expected=$expected_v03_sha" >&2
  echo "actual=$actual_v03_sha" >&2
  exit 2
}

if [[ -s "$STAGE_QC" ]] && awk -F '\t' '$1=="audit_status"{print $2}' "$STAGE_QC" | tr -d '\015' | grep -qx 'PASS'; then
  echo "STAGE12E_ALREADY_PASS"
  cat "$STAGE_QC"
  exit 0
fi

for d in "$BENCH" "$QC_DIR" "$TMP"; do
  [[ ! -e "$d" ]] || { echo "ERROR: existing incomplete Stage 12E output; refusing overwrite: $d" >&2; exit 2; }
done
[[ ! -e "$CALLER_V04" ]] || { echo "ERROR: v0.4.0 caller already exists without Stage 12E PASS: $CALLER_V04" >&2; exit 2; }

mkdir -p "$BENCH" "$QC_DIR" "$TMP" "$SCRIPT_DIR" "$(dirname "$NOTE")"

cleanup_fail() {
  rc=$?
  if (( rc != 0 )); then
    echo "ERROR: Stage 12E failed; v0.3.0 remains active and v0.4.0 was not promoted" >&2
    rm -f "$CALLER_V04.part"
  fi
  exit "$rc"
}
trap cleanup_fail EXIT

SELF="$(readlink -f "$0")"
if [[ "$SELF" != "$SCRIPT_INSTALL" && ! -e "$SCRIPT_INSTALL" ]]; then
  cp "$SELF" "$SCRIPT_INSTALL.part"
  chmod 0755 "$SCRIPT_INSTALL.part"
  mv "$SCRIPT_INSTALL.part" "$SCRIPT_INSTALL"
fi

echo "===== BUILD v0.4.0 CANDIDATE ====="
python - "$CALLER_V03" "$CANDIDATE" <<'PYPATCH'
from pathlib import Path
import sys, py_compile, hashlib
src=Path(sys.argv[1]); out=Path(sys.argv[2])
text=src.read_text(encoding="utf-8")
old_version="CALLER_VERSION='rnatr_general_repeat_caller_ref_v0.3.0'"
new_version="CALLER_VERSION='rnatr_general_repeat_caller_ref_v0.4.0'"
old="""def _candidate_windows(seq_len:int,prior_start:int,prior_end:int,p:int):
    span=prior_end-prior_start
    max_margin=max(50,span)
    margins=[0,p,2*p,4*p,8*p,max(12,span//2),max_margin]
    out=[]; seen=set()
    for m in margins:
        m=min(max_margin,max(0,int(m)))
        lo=max(0,prior_start-m); hi=min(seq_len,prior_end+m)
        if hi<=lo or (lo,hi) in seen: continue
        seen.add((lo,hi)); out.append((lo,hi))
    return out
"""
new="""def _candidate_windows(seq_len:int,prior_start:int,prior_end:int,p:int):
    span=prior_end-prior_start
    # Geometric expansion beyond a short projected prior. Every accepted alignment
    # must still overlap the projected locus core, so remote repeat tracts cannot
    # replace the locus merely because they are longer.
    max_margin=max(prior_start,seq_len-prior_end)
    base=max(12,span//2,p)
    margins=[0,p,2*p,4*p,8*p,base,max(50,span)]
    m=max(50,span)
    while m < max_margin:
        m=min(max_margin,max(m+1,2*m))
        margins.append(m)
    margins.append(max_margin)
    out=[]; seen=set()
    for m in margins:
        m=min(max_margin,max(0,int(m)))
        lo=max(0,prior_start-m); hi=min(seq_len,prior_end+m)
        if hi<=lo or (lo,hi) in seen: continue
        seen.add((lo,hi)); out.append((lo,hi))
    return out
"""
if text.count(old_version)!=1: raise SystemExit("ERROR: caller version anchor mismatch")
if text.count(old)!=1: raise SystemExit("ERROR: candidate-window anchor mismatch")
text=text.replace(old_version,new_version,1).replace(old,new,1)
out.write_text(text,encoding="utf-8")
py_compile.compile(str(out),doraise=True)
print("candidate_sha256\t"+hashlib.sha256(out.read_bytes()).hexdigest())
PYPATCH

echo "===== STAGE 12E CANDIDATE DEPENDENCY MATERIALIZATION ====="
cp "$CALLER_V02" "$TMP/rnatr_general_repeat_caller_ref_v0.2.0.py.part"
[[ "$(sha256sum "$TMP/rnatr_general_repeat_caller_ref_v0.2.0.py.part" | awk '{print $1}')" == "$expected_v02_sha" ]] || {
  rm -f "$TMP/rnatr_general_repeat_caller_ref_v0.2.0.py.part"
  echo "ERROR: copied v0.2.0 dependency SHA mismatch" >&2
  exit 2
}
mv "$TMP/rnatr_general_repeat_caller_ref_v0.2.0.py.part" "$TMP/rnatr_general_repeat_caller_ref_v0.2.0.py"
python -m py_compile "$CANDIDATE" "$TMP/rnatr_general_repeat_caller_ref_v0.2.0.py"
python - "$CANDIDATE" <<'PYIMPORT'
import importlib.util,sys
from pathlib import Path
p=Path(sys.argv[1])
spec=importlib.util.spec_from_file_location('rnatr_v040_candidate_importcheck',p)
mod=importlib.util.module_from_spec(spec); sys.modules[spec.name]=mod; spec.loader.exec_module(mod)
assert getattr(mod,'CALLER_VERSION',None)=='rnatr_general_repeat_caller_ref_v0.4.0'
print('CANDIDATE_IMPORT_WITH_V02_DEPENDENCY_PASS')
PYIMPORT

echo "===== INSTALL BENCHMARK DRIVER ====="
BENCH_B64=''
python - "$BENCH_SCRIPT" "$BENCH_B64" <<'PYBENCH'
from pathlib import Path
import base64,sys,hashlib,py_compile
p=Path(sys.argv[1]); data=base64.b64decode(sys.argv[2])
if p.exists():
    if p.read_bytes()!=data: raise SystemExit(f"ERROR: existing benchmark driver differs: {p}")
else:
    tmp=p.with_name("."+p.name+".part"); tmp.write_bytes(data); tmp.chmod(0o755); tmp.replace(p)
py_compile.compile(str(p),doraise=True)
print("benchmark_driver_sha256\t"+hashlib.sha256(p.read_bytes()).hexdigest())
PYBENCH

echo "===== BACKWARD REGRESSION SELFTESTS ====="
python "$SELFTEST_V01" --caller "$CANDIDATE" --outdir "$BENCH/simple_periodic"
python "$SELFTEST_V02" --caller "$CANDIDATE" --outdir "$BENCH/compound_interruption_lps"
python "$SELFTEST_V03" --caller "$CANDIDATE" --outdir "$BENCH/boundary_censor_denovo"

echo "===== DISEASE-INSPIRED + BROAD SIMULATION BENCHMARK ====="
python "$BENCH_SCRIPT" --caller "$CANDIDATE" --outdir "$BENCH/disease_sim"

echo "===== REAL P0/P1 ENGINEERING REGRESSION ====="
python - "$CANDIDATE" "$FIXTURES_REAL" "$V03_REAL_QC" "$BENCH/real_p01_regression_calls.v0.4.0.tsv" "$BENCH/real_p01_regression.qc.tsv" <<'PYREAL'
from __future__ import annotations
import csv, importlib.util, sys, statistics, math, os
from pathlib import Path

def load(path):
    spec=importlib.util.spec_from_file_location("rnatr_v040_real",path)
    mod=importlib.util.module_from_spec(spec);sys.modules[spec.name]=mod;spec.loader.exec_module(mod);return mod

def qctsv(path):
    with Path(path).open() as fh:
        return {r["metric"]:r["value"].rstrip("\r") for r in csv.DictReader(fh,delimiter="\t")}

def percentile(vals,q):
    s=sorted(float(x) for x in vals)
    if not s:return None
    if len(s)==1:return s[0]
    pos=(len(s)-1)*q;lo=math.floor(pos);hi=math.ceil(pos)
    return s[lo] if lo==hi else s[lo]*(hi-pos)+s[hi]*(pos-lo)

caller=load(Path(sys.argv[1])); fixtures=Path(sys.argv[2]); oldqc=qctsv(sys.argv[3]); out=Path(sys.argv[4]); qc=Path(sys.argv[5])
with fixtures.open() as fh: rows=list(csv.DictReader(fh,delimiter="\t"))
if len(rows)!=60: raise SystemExit(f"ERROR: expected 60 real fixtures, got {len(rows)}")
res=[];absd=[];motifok=[];overlaps=[];context_limited=0;gt50=0;gt100=0;ext50=0
for r in rows:
    geom=r.get("evidence_class","SPAN") or "SPAN"
    context="PROJECTION_WINDOW" if r.get("materialization_mode")=="PROJECTION_WINDOW_FASTQ" else "FULL_READ"
    c=caller.call_repeat(r["sequence"],int(r["prior_start"]),int(r["prior_end"]),[r["canonical_motif"]],
                         evidence_geometry=geom,sequence_context=context)
    frozen=float(r["repeat_bp_estimate"]);delta=float(c.repeat_bp_observed)-frozen;ad=abs(delta);absd.append(ad)
    truth=caller.canonical_motif(r["canonical_motif"]);ok=c.canonical_motif==truth;motifok.append(ok);overlaps.append(c.prior_overlap_bp)
    context_limited+=int(c.context_limited);gt50+=int(ad>50);gt100+=int(ad>100)
    ext=max(0,int(c.left_extension_bp))+max(0,int(c.right_extension_bp));ext50+=int(ext>50)
    d=c.__dict__.copy()
    res.append({"projection_id":r["projection_id"],"read_id":r["read_id"],"representative_locus_id":r.get("representative_locus_id",""),
                "frozen_canonical_motif":r["canonical_motif"],"frozen_repeat_bp_estimate":r["repeat_bp_estimate"],
                "new_canonical_motif":c.canonical_motif,"motif_concordant":str(ok).lower(),
                "new_repeat_bp_observed":c.repeat_bp_observed,"new_minus_frozen_bp":delta,"abs_new_minus_frozen_bp":ad,
                "materialization_mode":r.get("materialization_mode",""),**d})
tmp=out.with_name("."+out.name+".part")
with tmp.open("w",newline="") as fh:
    wr=csv.DictWriter(fh,fieldnames=list(res[0]),delimiter="\t");wr.writeheader();wr.writerows(res)
os.replace(tmp,out)
motif_frac=sum(motifok)/len(motifok)
old_motif=float(oldqc.get("motif_concordance_fraction","nan"))
status=(len(res)==60 and all(x>0 for x in overlaps) and motif_frac>=old_motif-0.05)
metrics=[
 ("fixture_rows",len(rows)),("caller_completed_rows",len(res)),("all_calls_overlap_prior",str(all(x>0 for x in overlaps)).lower()),
 ("motif_concordance_fraction",motif_frac),("v0_3_motif_concordance_fraction",old_motif),
 ("abs_new_minus_frozen_median_bp",statistics.median(absd)),("abs_new_minus_frozen_p95_bp",percentile(absd,.95)),
 ("abs_delta_gt50_rows",gt50),("abs_delta_gt100_rows",gt100),("boundary_extension_gt50_rows",ext50),
 ("context_limited_rows",context_limited),("comparison_semantics","SOFTWARE_REGRESSION_DESCRIPTIVE_NOT_BIOLOGICAL_TRUTH"),
 ("promotion_guard","COMPLETION_PRIOR_ANCHORING_AND_NO_MAJOR_MOTIF_CONCORDANCE_REGRESSION"),
 ("regression_status","PASS" if status else "REVIEW")]
qc.parent.mkdir(parents=True,exist_ok=True);tmp=qc.with_name("."+qc.name+".part")
with tmp.open("w",newline="") as fh:
    wr=csv.writer(fh,delimiter="\t");wr.writerow(["metric","value"]);wr.writerows(metrics)
os.replace(tmp,qc);print(qc.read_text(),end="")
if not status: raise SystemExit(3)
PYREAL

echo "===== STAGE 12E PROMOTION QC ====="
python - "$BENCH/simple_periodic/synthetic_reference_selftest.qc.tsv" \
         "$BENCH/compound_interruption_lps/compound_interruption_lps_selftest.qc.tsv" \
         "$BENCH/boundary_censor_denovo/boundary_censor_denovo_selftest.qc.tsv" \
         "$BENCH/disease_sim/disease_sim_benchmark.qc.tsv" \
         "$BENCH/real_p01_regression.qc.tsv" \
         "$CANDIDATE" "$STAGE_QC" <<'PYSTAGE'
import csv,sys,hashlib,os
from pathlib import Path
def q(path):
    with Path(path).open() as fh:return {r["metric"]:r["value"].rstrip("\r") for r in csv.DictReader(fh,delimiter="\t")}
simple,compound,boundary,bench,real=map(q,sys.argv[1:6])
candidate=Path(sys.argv[6]);out=Path(sys.argv[7])
checks=[
 simple.get("selftest_status")=="PASS",
 compound.get("selftest_status")=="PASS",
 boundary.get("selftest_status")=="PASS",
 bench.get("audit_status")=="PASS",
 bench.get("semantic_invariants_status")=="PASS",
 bench.get("expansion_stress_status")=="PASS",
 real.get("regression_status")=="PASS",
]
status="PASS" if all(checks) else "REVIEW"
metrics=[
 ("stage_version","rnatr_general_repeat_caller_disease_sim_and_expansion_patch_v0.4.0"),
 ("wrapper_version","12e_run_disease_sim_and_promote_v0.4.1"),
 ("simple_periodic_regression",simple.get("selftest_status")),
 ("compound_interruption_lps_regression",compound.get("selftest_status")),
 ("boundary_censor_denovo_regression",boundary.get("selftest_status")),
 ("disease_sim_benchmark",bench.get("audit_status")),
 ("disease_exact_boundary_motif_accuracy",bench.get("disease_exact_boundary_motif_accuracy")),
 ("disease_exact_boundary_abs_error_median_bp",bench.get("disease_exact_boundary_abs_error_median_bp")),
 ("disease_exact_boundary_abs_error_p95_bp",bench.get("disease_exact_boundary_abs_error_p95_bp")),
 ("expansion_stress_recovery_fraction_median",bench.get("expansion_stress_recovery_fraction_median")),
 ("expansion_stress_recovery_fraction_p10",bench.get("expansion_stress_recovery_fraction_p10")),
 ("censored_semantic_invariants",bench.get("semantic_invariants_status")),
 ("denovo_motif_accuracy",bench.get("denovo_motif_accuracy")),
 ("compound_classification_fraction",bench.get("compound_classification_fraction")),
 ("interruption_classification_fraction",bench.get("interruption_classification_fraction")),
 ("benchmark_runtime_total_seconds",bench.get("runtime_total_seconds")),
 ("benchmark_runtime_per_call_median_ms",bench.get("runtime_per_call_median_ms")),
 ("real_regression_status",real.get("regression_status")),
 ("real_motif_concordance_fraction",real.get("motif_concordance_fraction")),
 ("real_abs_delta_median_bp",real.get("abs_new_minus_frozen_median_bp")),
 ("real_abs_delta_p95_bp",real.get("abs_new_minus_frozen_p95_bp")),
 ("real_context_limited_rows",real.get("context_limited_rows")),
 ("candidate_sha256",hashlib.sha256(candidate.read_bytes()).hexdigest()),
 ("benchmark_semantics","MEASUREMENT_VALIDATION_NOT_PATHOGENICITY_NOT_POPULATION_CALIBRATION"),
 ("performance_optimization","NEXT_AFTER_GENERAL_CALLER_FREEZE"),
 ("ssot_update_status","PENDING_AFTER_STAGE12E_RESULT_REVIEW"),
 ("next_gate","FREEZE_GENERAL_CALLER_V0.4_IF_PROMOTED_THEN_PROFILE_11F_11H_AND_BUILD_PRODUCTION_INTEGRATION"),
 ("audit_status",status),
]
out.parent.mkdir(parents=True,exist_ok=True);tmp=out.with_name("."+out.name+".part")
with tmp.open("w",newline="") as fh:
    wr=csv.writer(fh,delimiter="\t");wr.writerow(["metric","value"]);wr.writerows(metrics)
os.replace(tmp,out);print(out.read_text(),end="")
if status!="PASS":raise SystemExit(3)
PYSTAGE

echo "===== PROMOTE v0.4.0 REFERENCE CALLER ====="
cp "$CANDIDATE" "$CALLER_V04.part"
chmod 0755 "$CALLER_V04.part"
mv "$CALLER_V04.part" "$CALLER_V04"

cat > "$NOTE.part" <<'EOF'
# RNA-TR-Scout general repeat caller reference v0.4.0

Stage 12E adds geometrically expanding, locus-anchored search windows after motif anchoring.

Purpose:
- recover long continuous repeat tracts when the projected/catalog prior covers only a short core;
- preserve the v0.3.0 requirement that every accepted tract overlap the projected locus core;
- retain explicit censoring and projection-context semantics from v0.3.0.

The disease-inspired benchmark uses known repeat motifs only as realistic sequence shapes. It does not apply disease thresholds, infer pathogenicity, estimate population normal ranges, or infer personal DNA genotype.

Promotion requires:
- v0.1.0 simple-periodic regression PASS;
- v0.2.0 compound/interruption/LPS regression PASS;
- v0.3.0 boundary/censor/de-novo regression PASS;
- broad simulation semantic invariants PASS;
- short-prior long-expansion recovery median >=0.90 and p10 >=0.80;
- real P0/P1 engineering regression completion, locus anchoring, and no major motif-concordance regression.

Performance optimization remains a separate next-stage task after semantic freeze.
EOF
mv "$NOTE.part" "$NOTE"

trap - EXIT
rm -rf "$TMP"

echo
echo "Caller: $CALLER_V04"
echo "Bench:  $BENCH"
echo "QC:     $STAGE_QC"
echo "Note:   $NOTE"
echo "STAGE12E_PASS"
echo "NOTE: failed v0.4.0-wrapper scratch was not modified; v0.4.1 used isolated output roots."
